class LmdbPlanningGraphEvidenceTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI FIRST_GRAPH = VF.createIRI("urn:planning-graph:first");
	private static final IRI SECOND_GRAPH = VF.createIRI("urn:planning-graph:second");
	private static final QuadSnapshotIdentity SNAPSHOT = new QuadSnapshotIdentity(1L, 2L, 3L);

	@Test
	void detachedAbsenceDoesNotGrantNativeEvidence() {
		StatementPattern pattern = pattern();
		assertFalse(LmdbPlanningGraphEvidence.allows(pattern));
		assertFalse(EstimateContext.root(pattern, SNAPSHOT, 3L).nativeEvidenceAllowed());
		PlanningGraphDomains.capture(pattern, PlanningGraphDomain.defaultGraph());
		assertTrue(LmdbPlanningGraphEvidence.allows(pattern));
		assertTrue(EstimateContext.root(pattern, SNAPSHOT, 3L).nativeEvidenceAllowed());
	}

	@Test
	void detachedCloneRetainsSelectorAndEstimatorCacheIdentity() {
		Graph first = graph(FIRST_GRAPH);
		Graph second = graph(SECOND_GRAPH);
		PlanningGraphDomains.capture(first, PlanningGraphDomain.defaultGraph());
		PlanningGraphDomains.capture(second, PlanningGraphDomain.defaultGraph());
		assertEquals(first.getArg(), second.getArg(), "Only the inherited graph domain differs between the bodies");
		assertNotEquals(FactorCostCacheKey.factorFingerprint(first.getArg()),
				FactorCostCacheKey.factorFingerprint(second.getArg()));
		TupleExpr detached = first.getArg().clone();
		assertEquals(PlanningGraphDomains.domain(first.getArg()), PlanningGraphDomains.domain(detached));
		assertFalse(LmdbPlanningGraphEvidence.allows(detached));
		assertEquals(FactorCostCacheKey.factorFingerprint(first.getArg()),
				FactorCostCacheKey.factorFingerprint(detached));
	}

	@Test
	void mixedPrefixCannotBorrowItsFirstDefaultFact() {
		StatementPattern ordinary = pattern();
		PlanningGraphDomains.capture(ordinary, PlanningGraphDomain.defaultGraph());
		Graph selected = graph(FIRST_GRAPH);
		PlanningGraphDomains.capture(selected, PlanningGraphDomain.defaultGraph());
		for (List<TupleExpr> factors : List.of(List.of(ordinary, selected.getArg()),
				List.of(selected.getArg(), ordinary))) {
			TupleExpr prefix = LmdbEstimatorExpressionSupport.join(factors);
			assertEquals(PlanningGraphDomain.Kind.UNKNOWN, PlanningGraphDomains.domain(prefix).kind());
			assertFalse(LmdbPlanningGraphEvidence.allows(prefix));
			assertFalse(LmdbPlanningGraphEvidence.allowsAll(factors));
		}
		assertTrue(LmdbPlanningGraphEvidence.allows(ordinary), "The independent ordinary sibling keeps its own proof");
	}

	@Test
	void scopeOccurrenceSeparatesEqualSelectorBodies() {
		Graph left = graph(FIRST_GRAPH);
		Graph right = graph(FIRST_GRAPH);
		QueryRoot root = new QueryRoot(new Join(left, right));
		PlanningGraphDomains.capture(root, PlanningGraphDomain.defaultGraph());
		assertNotEquals(PlanningGraphDomains.domain(left.getArg()), PlanningGraphDomains.domain(right.getArg()));
		assertNotEquals(FactorCostCacheKey.factorFingerprint(left.getArg()),
				FactorCostCacheKey.factorFingerprint(right.getArg()));
	}

	@Test
	void selectorMutationInvalidatesOldAuthorityUntilRefresh() {
		Graph selected = graph(FIRST_GRAPH);
		PlanningGraphDomains.capture(selected, PlanningGraphDomain.defaultGraph());
		PlanningGraphDomain before = PlanningGraphDomains.domain(selected.getArg());
		selected.setGraphName(Var.of("graph", SECOND_GRAPH));
		assertEquals(PlanningGraphDomain.Kind.UNKNOWN, PlanningGraphDomains.domain(selected.getArg()).kind());
		PlanningGraphDomains.refresh(selected, PlanningGraphDomain.defaultGraph());
		assertNotEquals(before, PlanningGraphDomains.domain(selected.getArg()));
		assertEquals(SECOND_GRAPH, PlanningGraphDomains.domain(selected.getArg()).selector().value());
	}

	@Test
	void physicalNamedGraphLoweringRefreshesNativeEvidenceAuthority() {
		Graph selected = new Graph(Var.of("graph", FIRST_GRAPH, false, true), pattern());
		QueryRoot root = new QueryRoot(selected);
		PlanningGraphDomains.capture(root, PlanningGraphDomain.defaultGraph());
		assertFalse(LmdbPlanningGraphEvidence.allows(selected.getArg()));
		new GraphScopeOptimizer().optimize(root, null, EmptyBindingSet.getInstance());
		PlanningGraphDomains.refresh(root, PlanningGraphDomain.defaultGraph());
		StatementPattern lowered = assertInstanceOf(StatementPattern.class, root.getArg());
		assertEquals(StatementPattern.Scope.NAMED_CONTEXTS, lowered.getScope());
		assertEquals(FIRST_GRAPH, lowered.getContextVar().getValue());
		assertTrue(LmdbPlanningGraphEvidence.allows(lowered));
		assertTrue(EstimateContext.root(lowered, SNAPSHOT, 3L).nativeEvidenceAllowed());
	}

	@Test
	void universalRangeDoesNotProveSelectedGraphMembershipOrCount(@TempDir Path directory) {
		IRI predicate = VF.createIRI("urn:planning-graph:p");
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig("spoc,posc")
				.setOptimizerSamplingEnabled(false)
				.setBackgroundRawSamplingMaxMillisPerCycle(0L));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (var connection = repository.getConnection()) {
			connection.begin(IsolationLevels.SNAPSHOT);
			connection.add(VF.createIRI("urn:planning-graph:outside"), predicate,
					VF.createIRI("urn:planning-graph:iri-object"), SECOND_GRAPH);
			connection.add(VF.createIRI("urn:planning-graph:anchor"), VF.createIRI("urn:planning-graph:other"),
					VF.createIRI("urn:planning-graph:anchor-object"), FIRST_GRAPH);
			connection.commit();
			LmdbEvaluationStatistics statistics = assertInstanceOf(LmdbEvaluationStatistics.class,
					store.getSailStore().getEvaluationStatistics());
			LmdbEstimatorRuntime runtime = statistics.estimatorRuntime();
			try (LmdbSailStore.DatasetAdmission admission = store.getBackingStore()
					.beginDatasetAdmission(IsolationLevels.SNAPSHOT_READ, null)) {
				LmdbSailStore.ReadView view = admission.view();
				view.requireDictionaryTermSnapshot();
				try (TripleStore.PlanningReadPin ignored = runtime.pinPlanningReads(view.tripleTxn(),
						view.valueSnapshot())) {
					PackedPredicateRange range = new PackedPredicateRange();
					assertTrue(new LmdbPackedPredicateRangeProvider(runtime).describeObjectRange(predicate, range));
					assertEquals(PackedPredicateRange.STATE_KNOWN, range.state());
					assertEquals(PackedPredicateRange.KIND_IRI, range.kindBits(),
							"Every selected-graph subset retains the admitted snapshot's universal object-kind constraint");
					Graph selected = graph(FIRST_GRAPH);
					PlanningGraphDomains.capture(selected, PlanningGraphDomain.defaultGraph());
					assertFalse(LmdbEstimateClassification.databaseExact(runtime.estimate(selected.getArg())),
							"The global predicate's presence cannot certify this selected graph's membership or count");
					assertTrue(Double.isNaN(new LmdbPackedCostModel(runtime).certifyRootRows(selected, 1.0d)));
					Graph contradiction = new Graph(Var.of("graph", FIRST_GRAPH),
							new Filter(pattern(), new IsLiteral(Var.of("o"))));
					PlanningGraphDomains.capture(contradiction, PlanningGraphDomain.defaultGraph());
					LmdbPackedPredicateRangeProvider nativeRanges = new LmdbPackedPredicateRangeProvider(runtime);
					PackedPredicateRangeProvider conservativeRanges = new PackedPredicateRangeProvider() {
						@Override
						public boolean describeObjectRange(IRI name, PackedPredicateRange output) {
							return nativeRanges.describeObjectRange(name, output);
						}

						@Override
						public long predicateRangeVersion() {
							return nativeRanges.predicateRangeVersion();
						}
					};
					LmdbPackedCostModel costs = new LmdbPackedCostModel(runtime);
					PackedPlanCache.Context cacheContext = new PackedPlanCache.Context(1L, 2L, 3L, 4L,
							runtime.snapshotVersion(), costs.providerVersion(), runtime.snapshotVersion(),
							nativeRanges.predicateRangeVersion());
					List<Executable> checks = new ArrayList<>();
					checks.add(() -> assertRangePlan(true, new CascadesPlanner().optimize(contradiction.clone(),
							OptimizationGoal.root(contradiction, PhysicalProperties.ANY), costs, nativeRanges)
							.tupleExpr()));
					for (boolean nativeFirst : List.of(false, true)) {
						PackedPlanCache cache = new PackedPlanCache(16, 1);
						for (boolean nativeProof : List.of(nativeFirst, !nativeFirst, nativeFirst, !nativeFirst)) {
							checks.add(() -> assertRangePlan(nativeProof,
									new CascadesPlanner().optimize(contradiction.clone(),
											OptimizationGoal.root(contradiction, PhysicalProperties.ANY), cache,
											cacheContext, costs,
											nativeProof ? nativeRanges : conservativeRanges).tupleExpr()));
						}
					}
					assertAll("Pinned universal ranges and conservative identical-version providers must stay distinct",
							checks);
				}
			}
			try (var rows = connection.prepareTupleQuery("SELECT ?s ?o WHERE { GRAPH <" + FIRST_GRAPH
					+ "> { ?s <" + predicate + "> ?o FILTER(isIRI(?o)) } }").evaluate()) {
				assertFalse(rows.hasNext(), "An IRI-only global predicate still has no row in the selected graph");
			}
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void allQuadCapabilityRequiresTheExactLiveOutermostNativePair(boolean retire, @TempDir Path directory)
			throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setOptimizerSamplingEnabled(false)
				.setBackgroundRawSamplingMaxMillisPerCycle(0L);
		LmdbStore store = new LmdbStore(directory.resolve("store").toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			LmdbEstimatorRuntime runtime = assertInstanceOf(LmdbEvaluationStatistics.class,
					store.getSailStore().getEvaluationStatistics()).estimatorRuntime();
			LmdbPackedPredicateRangeProvider ranges = new LmdbPackedPredicateRangeProvider(runtime);
			assertEquals(RangeApplicability.CURRENT_DOMAIN, ranges.predicateRangeApplicability());
			try (LmdbSailStore.DatasetAdmission admission = store.getBackingStore()
					.beginDatasetAdmission(IsolationLevels.SNAPSHOT_READ, null)) {
				LmdbSailStore.ReadView view = admission.view();
				view.requireDictionaryTermSnapshot();
				try (TripleStore.PlanningReadPin ignored = runtime.pinPlanningReads(view.tripleTxn())) {
					assertEquals(RangeApplicability.CURRENT_DOMAIN, ranges.predicateRangeApplicability(),
							"A triple-only pin does not prove a paired dictionary view");
				}
				try (ValueStore.ReadSnapshotReservation reservation = runtime.valueStore().reserveReadSnapshot();
						ValueStore.ReadSnapshot dictionary = reservation.start();
						TripleStore.PlanningReadPin ignored = runtime.pinPlanningReads(view.tripleTxn(), dictionary)) {
					assertEquals(RangeApplicability.CURRENT_DOMAIN, ranges.predicateRangeApplicability(),
							"An unrelated dictionary snapshot does not belong to the supplied triple snapshot");
				}
				ValueStore foreign = new ValueStore(directory.resolve("foreign-values").toFile(), config);
				try (ValueStore.ReadSnapshotReservation reservation = foreign.reserveReadSnapshot();
						ValueStore.ReadSnapshot dictionary = reservation.start()) {
					assertThrows(IllegalArgumentException.class,
							() -> runtime.pinPlanningReads(view.tripleTxn(), dictionary));
					assertEquals(RangeApplicability.CURRENT_DOMAIN, ranges.predicateRangeApplicability(),
							"Failed dictionary admission must release the partial triple pin");
				} finally {
					foreign.close();
				}
				try (TripleStore.PlanningReadPin ignored = runtime.pinPlanningReads(view.tripleTxn(),
						view.valueSnapshot())) {
					assertEquals(RangeApplicability.ALL_QUADS, ranges.predicateRangeApplicability());
					try (TripleStore.PlanningReadPin nested = runtime.pinPlanningReads(view.tripleTxn(),
							view.valueSnapshot())) {
						assertEquals(RangeApplicability.ALL_QUADS, ranges.predicateRangeApplicability());
					}
					assertEquals(RangeApplicability.ALL_QUADS, ranges.predicateRangeApplicability(),
							"Closing a nested borrower must retain the original pair");
					try (ValueStore.ReadSnapshotReservation reservation = runtime.valueStore().reserveReadSnapshot();
							ValueStore.ReadSnapshot innerDictionary = reservation.start();
							TripleStore.PlanningReadPin nested = runtime.pinPlanningReads(view.tripleTxn(),
									innerDictionary)) {
						assertEquals(RangeApplicability.ALL_QUADS, ranges.predicateRangeApplicability(),
								"The actual outermost pair survives an ignored inner dictionary argument");
					}
					if (retire) {
						view.valueSnapshot().retireForMapResize(LmdbSailStore.MapResizeKind.VALUE_STORE);
					} else {
						view.valueSnapshot().close();
					}
					assertEquals(RangeApplicability.CURRENT_DOMAIN, ranges.predicateRangeApplicability(),
							"A closed or retired dictionary cannot certify the still-pinned triple reader");
				}
				assertEquals(RangeApplicability.CURRENT_DOMAIN, ranges.predicateRangeApplicability());
			}
		} finally {
			repository.shutDown();
		}
	}

	private static void assertRangePlan(boolean nativeProof, TupleExpr selectedPlan) {
		int[] nodes = new int[3];
		selectedPlan.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(EmptySet empty) {
				nodes[0]++;
			}

			@Override
			public void meet(StatementPattern statement) {
				nodes[1]++;
			}

			@Override
			public void meet(Filter filter) {
				nodes[2]++;
				super.meet(filter);
			}
		});
		if (nativeProof) {
			assertTrue(nodes[0] > 0,
					() -> "The actual pinned all-quad IRI range must eliminate the impossible RDF-kind filter inside "
							+ "retained GRAPH without borrowing a selected-graph count\n" + selectedPlan);
			assertEquals(0, nodes[1], () -> "The universal contradiction needs no statement scan\n" + selectedPlan);
		} else {
			assertEquals(0, nodes[0],
					() -> "A conservative current-domain provider cannot transfer this proof\n" + selectedPlan);
			assertEquals(1, nodes[1], () -> "The selected-graph statement must remain\n" + selectedPlan);
			assertEquals(1, nodes[2], () -> "The unproved selected-graph filter must remain\n" + selectedPlan);
		}
	}

	private static Graph graph(IRI name) {
		return new Graph(Var.of("graph", name), pattern());
	}

	private static StatementPattern pattern() {
		return new StatementPattern(Var.of("s"), Var.of("p", VF.createIRI("urn:planning-graph:p")), Var.of("o"));
	}
}
